// Purpose: Verify Recovery Contract. Keep this deterministic and fail closed.
const o = $('Prepared Outbox Input').first().json, m = $json, h = $('SHA-256 Recovered Delta').item.json.recovered_sha256;
const text = value => String(value ?? '').trim();
if (h !== o.delta_sha256 || m.schema_version !== o.delta_schema_version || m.actual_file_id !== o.actual_file_id || m.config_version !== o.config_version || !m.card_code)
    throw new Error('OUTBOX_RECOVERY_ARTIFACT_MISMATCH');
if (text(m.account_id) !== text(o.account_id) || text(m.card_code).toUpperCase() !== text(o.card_code).toUpperCase())
    throw new Error('OUTBOX_RECOVERY_ACCOUNT_BINDING_MISMATCH');
if (!Array.isArray(m.transactions) || !m.transactions.length)
    throw new Error('OUTBOX_RECOVERY_EMPTY');
const historical = m.historical_import === true;
if (historical && (m.source_code !== 'ADCB_CASHBACK' || m.historical_source !== 'ADCB_CASHBACK' || text(m.historical_account_id) !== text(m.account_id)))
    throw new Error('OUTBOX_RECOVERY_HISTORICAL_BINDING_MISMATCH');
return [{ json: { outbox_row: o, manifest: m, verification: { account_id: m.account_id, card_code: m.card_code, start_date: m.period_start, end_date: m.period_end, expected_transactions: m.transactions, expected_account_balance: m.expected_statement_balance_minor } } }];

// Purpose: Build Recovery Lease Acquire Request. Keep this deterministic and fail closed.
const r = $json;
return [{ json: { operation: 'ACQUIRE', resource_key: `actual:${r.outbox_row.actual_file_id}`, lease_owner: `n8n:recovery:${r.outbox_row.batch_id}`, ttl_seconds: 120 } }];

// Purpose: Build Fenced Recovery Envelope. Keep this deterministic and fail closed.
const r = $('Verify Recovery Contract').first().json, l = $json, o = r.outbox_row, m = r.manifest;
const text = value => String(value ?? '').trim();
if (!l.lease_id || Number(l.fencing_token) <= 0 || new Date(l.expires_at) <= new Date())
    throw new Error('RECOVERY_WRITER_LEASE_INVALID');
if (text(m.account_id) !== text(o.account_id) || text(m.card_code).toUpperCase() !== text(o.card_code).toUpperCase())
    throw new Error('OUTBOX_RECOVERY_ACCOUNT_BINDING_MISMATCH');
const outboxId = text(o.outbox_id || o.batch_id);
if (!outboxId)
    throw new Error('OUTBOX_RECOVERY_ID_MISSING');
const historical = m.historical_import === true;
if (historical && (m.source_code !== 'ADCB_CASHBACK' || m.historical_source !== 'ADCB_CASHBACK' || text(m.historical_account_id) !== text(m.account_id)))
    throw new Error('OUTBOX_RECOVERY_HISTORICAL_BINDING_MISMATCH');
return [{ json: { original_state: o.state, outbox: { schema_version: 1, outbox_id: outboxId, state: 'PREPARED', account_id: text(m.account_id), card_code: text(m.card_code), ...(historical ? { historical_import: true, historical_source: 'ADCB_CASHBACK', historical_account_id: text(m.historical_account_id) } : {}), execution_context: { trigger: 'RECOVERY', manual: false, mcp: false }, transactions: m.transactions, writer_lease: { lease_id: String(l.lease_id), fencing_token: Number(l.fencing_token), expires_at: String(l.expires_at) } }, verification: r.verification } }];

// Purpose: Build Recovery Fence Assert. Keep this deterministic and fail closed.
const l = $('Acquire Recovery Writer Fence').first().json;
return [{ json: { operation: 'ASSERT', resource_key: l.resource_key, lease_id: l.lease_id, fencing_token: l.fencing_token } }];

// Purpose: Rebuild Asserted Recovery Envelope. Keep this deterministic and fail closed.
if ($json.valid !== true)
    throw new Error('RECOVERY_FENCE_ASSERTION_FAILED');
return [{ json: $('Build Fenced Recovery Envelope').first().json }];

// Purpose: Build Recovery Verification Contract. Keep this deterministic and fail closed.
const root = $('Verify Recovery Contract').first().json;
const manifest = root.manifest;
const verification = root.verification;
const expectedVerification = Object.fromEntries(Object.entries(verification).filter(([key]) => key !== 'expected_account_balance'));
const actualFrom = name => {
    try {
        return $(name).first().json.actual || {};
    }
    catch {
        return {};
    }
};
const preflight = actualFrom('Recovery Actual Preflight');
const resumedPreflight = actualFrom('Recovery Existing Actual Preflight');
const importObserved = actualFrom('Recovery Import PREPARED');
const observedState = $('Read Back ACTUAL OBSERVED Recovery').first().json;
const existingIds = [
    ...(Array.isArray(preflight.already_observed) ? preflight.already_observed : []),
    ...(Array.isArray(resumedPreflight.already_observed) ? resumedPreflight.already_observed : []),
    ...(Array.isArray(importObserved.reconciled_imported_ids) ? importObserved.reconciled_imported_ids : []),
];
if (!verification.card_code)
    throw new Error('RECOVERY_CARD_CODE_MISSING');
if (!Array.isArray(existingIds) || existingIds.some(id => typeof id !== 'string'))
    throw new Error('RECOVERY_PREFLIGHT_EXISTING_IDS_MISSING');
const expectedBalance = observedState.expected_account_balance;
const observedBalance = observedState.observed_account_balance;
if (typeof expectedBalance !== 'number' || typeof observedBalance !== 'number'
    || !Number.isSafeInteger(expectedBalance) || !Number.isSafeInteger(observedBalance)
    || expectedBalance !== observedBalance)
    throw new Error('RECOVERY_IMPORT_BALANCE_DELTA_EVIDENCE_MISSING');
return [{ json: {
            verification: { ...expectedVerification, preserve_manual_fields_for_ids: [...new Set(existingIds)].sort() },
            balance_evidence: { expected: expectedBalance, observed: observedBalance },
        } }];

// Purpose: Build Recovery Fence Release. Keep this deterministic and fail closed.
const l = $('Acquire Recovery Writer Fence').first().json;
return [{ json: { operation: 'RELEASE', resource_key: l.resource_key, lease_id: l.lease_id, lease_owner: l.lease_owner, fencing_token: l.fencing_token } }];

// Purpose: Return Verified Commit Receipt. Keep this deterministic and fail closed.
const committed = $('Read Back COMMITTED Recovery').first().json;
const receipt = $('Validate Stored Verification Receipt for Commit').first().json;
const release = $('Read Back Released Recovery Writer Fence').first().json;
const lease = $('Build Recovery Fence Release').first().json;
if (!receipt || !receipt.card_code || receipt.invariants_passed !== true || committed.state !== 'COMMITTED')
    throw new Error('ACTUAL_COMMIT_RECEIPT_NOT_TRUSTED');
if (String(committed.lease_owner) !== String(lease.lease_owner)
    || Number(committed.lease_fence) !== Number(lease.fencing_token))
    throw new Error('ACTUAL_WRITER_LEASE_CORRELATION_NOT_READ_BACK');
if (!release || release.released !== true
    || String(release.resource_key) !== String(lease.resource_key)
    || String(release.lease_id) !== String(lease.lease_id)
    || String(release.lease_owner) !== String(lease.lease_owner)
    || Number(release.fencing_token) !== Number(lease.fencing_token))
    throw new Error('ACTUAL_WRITER_LEASE_RELEASE_NOT_READ_BACK');
return [{
        json: {
            batch_id: committed.batch_id,
            actual_file_id: receipt.actual_file_id,
            account_id: receipt.account_id,
            card_code: receipt.card_code,
            state: committed.state,
            verification_version: Number(receipt.verification_version),
            period_start: receipt.period_start,
            period_end: receipt.period_end,
            expected_payload_sha256: receipt.expected_payload_sha256,
            observed_payload_sha256: receipt.observed_payload_sha256,
            expected_count: receipt.expected_count,
            observed_count: receipt.observed_count,
            expected_amount_sum_minor: receipt.expected_amount_sum_minor,
            observed_amount_sum_minor: receipt.observed_amount_sum_minor,
            expected_account_balance: receipt.expected_account_balance,
            observed_account_balance: receipt.observed_account_balance,
            invariants_passed: receipt.invariants_passed,
            verified_at: receipt.verified_at,
            lease_owner: committed.lease_owner,
            lease_fence: Number(committed.lease_fence),
            writer_release_verified: true,
        },
    }];

// Purpose: Build Post-Import Fence Assert. Keep this deterministic and fail closed.
const lease = $('Acquire Recovery Writer Fence').first().json;
return [{ json: { operation: 'ASSERT', resource_key: lease.resource_key, lease_id: lease.lease_id, fencing_token: lease.fencing_token } }];

// Purpose: Restore Post-Import Result. Keep this deterministic and fail closed.
if ($json.valid !== true)
    throw new Error('RECOVERY_POST_IMPORT_FENCE_ASSERTION_FAILED');
return [{ json: $('Recovery Import PREPARED').first().json }];

// Purpose: Build Pre-Commit Fence Assert. Keep this deterministic and fail closed.
const lease = $('Acquire Recovery Writer Fence').first().json;
return [{ json: { operation: 'ASSERT', resource_key: lease.resource_key, lease_id: lease.lease_id, fencing_token: lease.fencing_token } }];
